      "time": "20 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 4 of the Web Research Agent - the command you actually run.\n\nRun it with:  python main.py \"your research topic\"\n\"\"\"\n\nimport sys\n\nfrom citations import build_reference_list\nfrom report import save_report\nfrom scraper import fetch_full_text, is_thin\nfrom sdt_ai import AIError\nfrom search import SearchError, run_search\nfrom synthesize import synthesize\n\n\ndef research(topic):\n    \"\"\"\n    Runs one full research pass: search, scrape thin sources, synthesize,\n    save. Returns the saved report's path.\n    \"\"\"\n    print(f\"Searching for: {topic}\\n\")\n    sources = run_search(topic)\n\n    if not sources:\n        raise ValueError(\"Tavily returned no usable results for that topic. Try rephrasing it.\")\n\n    print(f\"Found {len(sources)} sources. Checking which ones need a deeper fetch...\\n\")\n    for source in sources:\n        if is_thin(source[\"snippet\"]):\n            full_text = fetch_full_text(source[\"url\"])\n            if full_text:\n                source[\"snippet\"] = full_text\n                print(f\"  Fetched full text for: {source['title']}\")\n\n    print(\"\\nAsking the AI to synthesize the brief...\\n\")\n    brief = synthesize(topic, sources)\n    references = build_reference_list(sources)\n\n    return save_report(topic, brief, references)\n\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 2:\n        print('Usage: python main.py \"your research topic\"')\n        sys.exit(1)\n\n    topic = \" \".join(sys.argv[1:])\n\n    try:\n        path = research(topic)\n    except SearchError as problem:\n        print(f\"Search failed:\\n{problem}\")\n        sys.exit(1)\n    except AIError as problem:\n        print(f\"AI request failed:\\n{problem}\")\n        sys.exit(1)\n    except ValueError as problem:\n        print(f\"Could not complete the research:\\n{problem}\")\n        sys.exit(1)\n\n    print(f\"\\nDone. Report saved to: {path}\")\n",
          "verify": "Run `python main.py \"AI agents in enterprise sales operations\"`. You should see the search, fetch, and synthesis steps print as they happen, ending with `Done. Report saved to: reports\\report_ai-agents-in-enterprise-sales-operations_<timestamp>.md`. Open the file and confirm it has all 5 sections plus a References list, with [Source N] citations matching real URLs.",
          "instruction": "Create `main.py` with this code:"
        }
      ],
      "title": "Wire it into one command",
      "number": 4,
      "goFurther": "Run it again on a topic you expect to have very little real information available (something obscure or very recent). Confirm the DATAPOINTS and CONFLICTING sections correctly show their 'none found' defaults instead of the AI inventing numbers to fill the gap.",
      "description": "Search, scrape, synthesize, and save are each already written and tested on their own. This build is only the wiring, plus telling apart the three different ways a run can fail."
    },
    {
      "time": "25 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 5 of the Web Research Agent - one follow-up research round.\n\nThe first brief always has gaps. This file asks the AI to name up to 3\nfollow-up searches that would fill the biggest ones, so main.py can run\nthem and merge the new sources in before re-synthesizing.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Hard cap, not a suggestion. Each follow-up query costs one more Tavily\n# search AND makes the eventual re-synthesis prompt bigger (more sources\n# = more input tokens) - three is enough to meaningfully improve a brief\n# without letting one research run spiral into ten AI calls.\nMAX_FOLLOWUP_QUERIES = 3\n\n\ndef build_prompt(topic, brief):\n    brief_text = \"\\n\\n\".join(f\"{k}:\\n{v}\" for k, v in brief.items())\n    return f\"\"\"Below is a research brief on \"{topic}\". Identify the most important\ngaps or unanswered questions in it, and write up to {MAX_FOLLOWUP_QUERIES}\nfollow-up search queries that would help fill them.\n\nFormat your answer EXACTLY like this:\n\n[QUERIES]\none search query per line, {MAX_FOLLOWUP_QUERIES} lines maximum\n[END]\n\nIf the brief is already thorough and you can't identify any meaningful\ngap, write a single line: None needed\n\nBRIEF:\n{brief_text}\"\"\"\n\n\ndef parse_followup_queries(reply):\n    \"\"\"\n    Turns the AI's reply into a list of query strings (possibly empty).\n\n    Deliberately plain-text, one query per line - not a JSON array - for\n    the same reason every other AI reply in this course avoids JSON: one\n    stray comma, or a query that itself contains a quote mark, would\n    break a JSON parser, and a follow-up round isn't worth failing the\n    whole research run over.\n    \"\"\"\n    lines = []\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker == \"QUERIES\":\n            current = \"QUERIES\"\n            continue\n        if current != \"QUERIES\" or not line:\n            continue\n        if line.startswith(\"```\"):\n            continue\n        if line.lower() == \"none needed\":\n            continue\n        lines.append(line.lstrip(\"-* \").strip())\n\n    return lines[:MAX_FOLLOWUP_QUERIES]\n\n\ndef get_followup_queries(topic, brief):\n    \"\"\"\n    The main function. Give it the topic and the first brief, get back a\n    list of up to MAX_FOLLOWUP_QUERIES follow-up search query strings.\n    \"\"\"\n    prompt = build_prompt(topic, brief)\n    reply = ask_ai(prompt, max_tokens=200, project=\"web-research-agent-followup\")\n    return parse_followup_queries(reply)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no AI call,\n    # no API usage:  python followup.py\n\n    print(\"Checking a well-formed reply...\")\n    good_reply = \"\"\"[QUERIES]\nAI sales agent adoption statistics 2026\nenterprise AI agent ROI case studies\n[END]\"\"\"\n    queries = parse_followup_queries(good_reply)\n    assert queries == [\n        \"AI sales agent adoption statistics 2026\",\n        \"enterprise AI agent ROI case studies\",\n    ]\n    print(\"  OK -\", queries)\n\n    print(\"\\nChecking 'None needed' returns an empty list...\")\n    assert parse_followup_queries(\"[QUERIES]\\nNone needed\\n[END]\") == []\n    print(\"  OK\")\n\n    print(\"\\nChecking more than the cap gets truncated...\")\n    too_many = \"[QUERIES]\\n\" + \"\\n\".join(f\"query {i}\" for i in range(10)) + \"\\n[END]\"\n    assert len(parse_followup_queries(too_many)) == MAX_FOLLOWUP_QUERIES\n    print(f\"  OK - capped at {MAX_FOLLOWUP_QUERIES} even though 10 were given\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python followup.py` (no AI call, no quota spent). You should see the well-formed reply parsed into a 2-item list, `None needed` correctly returning an empty list, and 10 fake queries correctly truncated down to 3, ending with `All checks passed.`",
          "instruction": "Create `followup.py` with this code:"
